const { PGlite } = require('/workspace/scratch/01f9acde8f88/USKOCI-EAN/node_modules/@electric-sql/pglite');
const fs = require('node:fs');
(async () => {
  const db = new PGlite();
  await db.exec('CREATE SCHEMA private; SET check_function_bodies=false;');
  const statements = JSON.parse(fs.readFileSync('/workspace/scratch/01f9acde8f88/r10-location-create-fixture.json','utf8'));
  for (const sql of statements) await db.exec(sql);
  const { rows } = await db.query(`SELECT n.nspname||'.'||p.proname AS function_name,
     pg_get_function_identity_arguments(p.oid) AS args, format_type(p.prorettype,NULL) AS result,
     p.proisstrict AS strict,p.prosecdef AS definer,p.provolatile AS volatility,
     p.proconfig AS config,l.lanname AS language,md5(p.prosrc) AS body_md5
     FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
     JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='private' OR
       (n.nspname='public' AND p.proname LIKE 'rpc_ai_%') ORDER BY n.nspname,p.proname`);
  fs.writeFileSync('/workspace/scratch/01f9acde8f88/r10-location-parser-metadata.json',JSON.stringify(rows,null,2)+'\n');
  console.log(JSON.stringify({functions_created:rows.length,strict_true:rows.filter(x=>x.strict).map(x=>x.function_name),business_functions_executed:0}));
  await db.close();
})().catch(e => {console.error(e.message);process.exitCode=1;});

const { PGlite } = require('/workspace/scratch/01f9acde8f88/USKOCI-EAN/node_modules/@electric-sql/pglite');
const fs = require('node:fs');
const { createHash } = require('node:crypto');
(async () => {
 const db = new PGlite();
 const input = fs.readFileSync('/workspace/scratch/01f9acde8f88/r10-reconstructed99-attempt.json','utf8');
 const {rows} = await db.query(`WITH d(data) AS (VALUES ($1::jsonb)) SELECT jsonb_build_object(
 'functions',(select jsonb_agg(jsonb_build_object('signature',f->'signature','source',f->'bodyMd5','owner',f->'ownerOid','acl',f->'acl','definer',f->'definer','strict',f->'strict','volatility',f->'volatility','language',f->'languageOid','config',f->'config','args',f->'argsOid','result',f->'resultOid') order by f->>'signature') from jsonb_array_elements(data->'functions')f where(f->>'programMember')::boolean),
 'tables',(select jsonb_agg(jsonb_build_array(t->'table',t->'ownerOid',t->'acl',t->'rls',t->'forceRls') order by t->>'table') from jsonb_array_elements(data->'programTables')t),
 'triggerState',data->'triggerState')::text AS document FROM d`,[input]);
 const sha = createHash('sha256').update(rows[0].document).digest('hex');
 fs.writeFileSync('/workspace/scratch/01f9acde8f88/r10-attempt99-program-document.json',rows[0].document);
 console.log(JSON.stringify({pglite_program_document_sha256:sha}));
 await db.close();
})().catch(e => { console.error(e.message);process.exitCode=1; });
